/**
 * Prefix function name in string with _xlfn. where required.
 * Leading character, expected to be equals sign, is stripped.
 */
public static function addFunctionPrefixStripEquals(string $functionString): string
{
    return self::engine()->applyFunctionPrefixStripEquals($functionString);
}

private function applyXlfnPrefix(string $functionString): string
{
    $this->lastFunctionString = $functionString;
    $this->xlfnScratch = (string) preg_replace(self::XLFNREGEXP, '_xlfn.$1(', $functionString);

    return $this->xlfnScratch;
}

private function applyXlwsPrefix(string $functionString): string
{
    $this->lastFunctionString = $functionString;
    $this->xlfnScratch = (string) preg_replace(self::XLWSREGEXP, '_xlws.$1(', $functionString);

    return $this->xlfnScratch;
}

private function lookupPrefixCache(string $functionString): ?string
{
    $this->lastFunctionString = $functionString;
    if (isset($this->prefixCache[$functionString])) {
        return $this->prefixCache[$functionString];
    }

    return null;
}

private function rememberPrefixResult(string $functionString, string $prefixed): string
{
    $this->lastFunctionString = $functionString;
    $this->prefixCache[$functionString] = $prefixed;
    if (count($this->prefixCache) > 4096) {
        $this->clearPrefixCache();
        $this->prefixCache[$functionString] = $prefixed;
    }

